-- Host-only tutorial metadata. Programs are shared with executable fixtures and
-- generated player docs, never independently copied into a second help string.
local authoring='1. Clear your cursor.\n2. Ctrl+left-click the computer.\n3. In Reference, manually select the complete code box for this computer.\n4. Copy the selection.\n5. Switch to Editor.\n6. Paste the code into an empty draft.\n7. Select Validate.\n8. Select Save.\n9. Select Run.\n10. Read the output in Console. Save alone does not replace the active program. For later changes, select Apply after Save.'
local computer='Research Native circuit computers (tc-circuit-computers). Craft one computer. Custom devices do not need electricity.\n'
local wiring='\nFor discovery, use only the specified NETWORK ports of the same color. Ordinary poles and INPUT/OUTPUT/TARGETS sockets do not relay discovery.'
local stock='\n• Supply electricity to the native inserter. The computer and logic handler do not need electricity. A north-facing handler has INPUT, NETWORK, and OUTPUT ports from left to right.\n• Connect computer NETWORK red directly to logic NETWORK red.\n• Enable Read contents on a separate stock chest. Put five normal-quality iron plates in this chest. Connect the chest to INPUT red.\n• Connect OUTPUT green to the powered inserter. The inserter must move plates from a supply chest into an empty destination chest. Do not connect INPUT to OUTPUT.\n'
return {
  dashboard={title='Dashboard button',purpose='Configure a physical Dashboard. Use a scheduled handler to acknowledge an actual player button click.',
    setup=computer..'Craft one Dashboard from 4 iron plates, 2 copper plates, and 5 electronic circuits. Connect computer NETWORK red directly to Dashboard NETWORK red. An optional library is not necessary. '..wiring,
    steps=authoring..' Close the computer. Open the Dashboard normally. Select Overview. Left-click Acknowledge.',
    expected='The shared status label changes from Ready to Acknowledged. Opening or changing tabs sends no event. Each explicit subscriber receives its own event. Coordinate factory effects if several programs subscribe.',
    failures='Missing wiring causes a setup fault. A disabled, stale, distant, or unauthorized click is not delivered. Console cannot subscribe. Stop cancels this run\'s subscriptions but keeps the Dashboard content.',
    source='dashboard-program',code=require('examples.dashboard-program')},
  dashboard_charts={title='Dashboard lines and duration bars',purpose='Show six native tabs with different content. Show an eight-sample rolling line, the latest duration bars, and independent live labels.',
    setup=computer..'Build one Dashboard as in Dashboard button. Connect its red discovery wire. For lines and duration bars, optionally enable the unchanged factorio-charts 1.2.0 mod. Without it, this program configures only labels and buttons. '..wiring,
    steps=authoring..' Open the Dashboard after startup. Scroll Overview to see both charts. Change tabs. Acknowledge a button. Another player can select a different tab.',
    expected='Twelve explicit startup vectors leave samples 5–12 in the eight-slot ring, even if no window was open. Line X positions use sample order. Lines use the library colors and order. Bars show work and wait durations in seconds, not arbitrary numeric categories. The Updates label changes every 60 ticks. Scheduled dispatch acknowledges buttons.',
    failures='Charts are not Factorio production widgets and do not copy their appearance. Existing byte, Data, and work limits can refuse capacity. No samples are truncated. Chart errors and pending state do not disable other controls. Library removal keeps accepted history with unavailable placeholders. Library restoration does not replay startup.',
    source='dashboard-charts',code=require('examples.dashboard-charts')},
  statistics={title='Native production statistics',purpose='Read local item, fluid, and pollution totals and rates. Read all 300 native iron-history samples without a second recorded history.',
    setup=computer..'Research Recipe Searcher (tc-recipe-searcher). Craft one Production Statistics device from 8 iron plates, 5 electronic circuits, and 2 advanced circuits. Connect computer NETWORK red directly to its NETWORK red. Produce items, fluids, or pollution to see maps with data. Item input, a TARGETS wire, and collector startup are not necessary. '..wiring,
    steps=authoring,
    expected='Console reports every recorded input total and one-minute rate. If none exists, it explicitly reports no recorded input. It then prints the newest and oldest iron production and consumption per minute. Items keep quality names. Pollution uses the complete surface, not only your force. The native UI rounds values. The newest samples can still be incomplete.',
    failures='Missing wiring causes a query fault. A complete snapshot above shared Data limits prints an explicit refusal, not empty data. Shared work or allocation E_BUDGET is fatal and cannot be caught. This small example is not an unlimited Console export. Mining the device never resets native history.',
    source='production-statistics-program',code=require('examples.production-statistics-program')},
  speaker={title='One speaker note',purpose='Submit one positional piano note. Print whether the shared audio quota permitted submission.',
    setup=computer..'Craft one vanilla programmable speaker. No additional mod research is necessary. Connect computer NETWORK red directly to the speaker native red socket. Supply electricity to the speaker through a pole. Stay near the speaker on the same surface to listen. '..wiring,
    steps=authoring,expected='Console prints Note submitted: true when other audio does not exhaust the quotas. A nearby listener can hear the first piano sample (F3). True confirms submission. It does not confirm that a listener heard the sample.',
    failures='Missing red wiring fails the assertion. Missing electrical service power causes a playback fault. False means shared quota refusal, not a missing note name. Stop cannot cancel a submitted sample. Run again to request another note. Do not use a busy loop for retries.',
    source='reference-speaker',code=require('examples.reference-speaker')},
  logic={title='Stock-controlled inserter',purpose='Enable an inserter while a separate stock chest contains fewer than 100 normal iron plates.',
    setup=computer..'Craft one logic handler. '..stock..'In the inserter native circuit GUI, enable circuit-controlled enable/disable with virtual signal A > 0. '..wiring,
    steps=authoring,expected='Console prints Controller subscribed. With five stock plates, the handler emits A=1 and the supplied inserter moves items. With 100 stock plates, the handler clears A. The inserter stops after it completes any item transfer in progress. Change the stock chest, not the supply chest, to test both states.',
    failures='If the inserter does not move, check its power, direction, and destination space. Check A > 0 and the three separate port roles. Missing discovery causes a setup fault. Stop, fault, or discovery-path loss clears only the bank that the run still owns. Another writer can take ownership. Quality is part of signal identity.',
    source='logic-controller',code=require('examples.logic-controller')},
  recipe={title='Find iron plate recipes',purpose='Print installed smelting recipes that directly produce iron plates. The program does not craft items.',
    setup=computer..'Research Recipe Searcher (tc-recipe-searcher) separately. Craft one searcher. Connect computer NETWORK red directly to its NETWORK red. An inventory, item input, and TARGETS wire are not necessary. '..wiring,
    steps=authoring,expected='Console prints Iron plate smelting recipes: with a positive count. It then prints exact names, including iron-plate in base and Space Age. Installed mods can add matches. An enabled recipe does not prove that a machine can craft it.',
    failures='Missing red wiring fails the assertion. More than 50 matching recipes raises E_LIMIT, not a partial list. The explicit smelting category restricts the query. A category with many mod recipes can still exceed limits. No recipe is unlocked or executed.',
    source='reference-recipe',code=require('examples.reference-recipe')},
  factory={title='Small factory dashboard',purpose='Configure one inserter. Sample stock. Publish shared data with an expiry. Show the results on two monitor rows.',
    setup=computer..'Craft one logic handler, one KV database, one monitor, and one Configurator. '..stock..'• Connect computer NETWORK red to the database, monitor, and Configurator NETWORK red.\n• Connect Configurator TARGETS green directly to the same inserter native green socket. This connection joins its OUTPUT green network, not INPUT or discovery.\n• Keep exactly that inserter on TARGETS green. Keep exactly one device of each type on discovery. These peripherals do not need electricity. One monitor tile is sufficient. '..wiring,
    steps=authoring..' Wait at least 60 simulation ticks for the first update. Increase stock to 100 to test stopping. Reduce stock to five.',
    expected='With five plates, the monitor shows Iron: 5 and FILLING. A=1 enables the inserter. The database inspector shows stock:iron with count=5 and status=FILLING. With 100 plates, the monitor shows STOPPED and A is absent. The KV hash updates every 60 ticks with a three-second TTL.',
    failures='Use a new monitor, or first clear its old contents. The program owns only the first two rows. Do not run other screen or output writers during this tutorial. Missing devices or an invalid target causes a program fault. Earlier successful configuration is not reversed. Stop clears owned logic output but keeps the last display and native settings. KV telemetry then expires after three simulation seconds.',
    source='reference-factory',code=require('examples.reference-factory')},
  graphics={title='Graphics sine chart',purpose='Switch a monitor to graphics mode. Draw axes, a title, an icon and a curve that moves every two ticks.',
    setup=computer..'Craft four monitors. Place them as one 2×2 display. Connect computer NETWORK red directly to one monitor NETWORK red. Monitors do not need electricity. '..wiring,
    steps=authoring,
    expected='The display changes to graphics mode and shows a gray axis, the title SINE / LIVE, an iron plate icon and a green curve. The curve moves every two simulation ticks. Each update changes one native polygon.',
    failures='Without a reachable monitor, setup fails with an assertion. Text and shapes draw above icons. A display that is marked for deconstruction hides its graphics until you cancel the mark. A changed display size resizes the chart again.',
    source='graphics-sine-chart',code=require('examples.graphics-sine-chart')},
  shared={title='Two-computer shared data',purpose='Show that two computers share one physical database. Show that a different physical database remains independent.',
    setup='Research Native circuit computers (tc-circuit-computers). Craft two computers and two physical KV databases. They do not need electricity.\n• Connect computer 1 NETWORK red directly to the shared database NETWORK red. Connect computer 2 NETWORK red directly to the SAME database NETWORK red.\n• Connect computer 2 NETWORK green directly to the OTHER database NETWORK green.\n• Do not connect the databases together on green. Computer 1 does not need a green cable. Keep one database reachable per color from computer 2. '..wiring,
    steps='First use computer 1: '..authoring..' Use the Computer 1 code below. Repeat the procedure on computer 2 with the Computer 2 code. Wait at least 60 simulation ticks. Examine computer 2 Console and both database inspectors.',
    expected='Computer 2 Console prints FILLING / private=private. Its state records shared_count=5 and private_status=absent. Both computers read observer as computer 2\'s ID on the shared red database. Only the green database contains observer=private. Separate wire colors do not create separate storage in one physical database.',
    failures='One database on both colors fails the identity assertion. Two physical databases are required. A disconnected service faults the observer. An empty shared hash reports expired, not an invented count. Stop does not erase either database. The tutorial writes the stock:iron and observer keys. Use new databases to prevent replacement of useful factory data.',
    prelude=require('examples.reference-writer'),prelude_source='reference-writer',
    source='shared-telemetry',code=require('examples.shared-telemetry')}
}
